describe('Session Expiration', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.setCookie('session_token', 'expired_token'); // Simulate an expired session token
    });

    it('should display session expired message when token times out', () => {
        cy.intercept('GET', '/api/your-endpoint', {
            statusCode: 401,
            body: { message: 'Session expired' },
        }).as('getExpiredSession');

        cy.visit('/dashboard'); // Replace with the actual page that requires authentication
        cy.wait('@getExpiredSession');

        cy.get('.session-expired-message') // Replace with the actual selector for the message
            .should('be.visible')
            .and('contain', 'Your session has expired. Please log in again.');
    });

    it('should redirect to login page after session expired', () => {
        cy.intercept('GET', '/api/your-endpoint', {
            statusCode: 401,
            body: { message: 'Session expired' },
        }).as('getExpiredSession');

        cy.visit('/dashboard'); // Replace with the actual page that requires authentication
        cy.wait('@getExpiredSession');

        cy.url().should('include', '/login'); // Replace with the actual login page URL
    });
});
